// Разбор ответа модели: снимаем возможную обёртку из ``` и парсим JSON.
const params = $('1. Параметры промпта').all();
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const raw = String(item.json?.choices?.[0]?.message?.content ?? '');

  // 1. убрать markdown-обёртку, если модель её добавила
  let text = raw.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();

  // 2. если вокруг JSON есть пояснения — взять только объект
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start >= 0 && end > start) {
    text = text.slice(start, end + 1);
  }

  // 3. разобрать в объект
  let data = {};
  let parseError = null;
  try {
    data = JSON.parse(text);
  } catch (e) {
    parseError = e.message;
  }

  const src = params[i]?.json ?? {};
  out.push({
    json: {
      complaint: src.user_prompt ?? '',
      severity: String(data.severity ?? '').toLowerCase(),
      category: String(data.category ?? '').toLowerCase(),
      summary: data.summary ?? '',
      action: data.action ?? '',
      tokens_total: item.json?.usage?.total_tokens ?? null,
      parsed_ok: parseError === null,
      parse_error: parseError,
      model_text: raw
    }
  });
}

return out;
